-- คอมไพล์ task_17e9202f814842e3b6d91fabe785f479_050300_append_ss_esim_temp.sql กับฐานจริงแบบไม่ดึงข้อมูล (WHERE 1=0) · SELECT อย่างเดียว
SELECT * FROM (
SELECT CAST(TO_CHAR(first_installed, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,cdr_source_path ,filter_dtm ,create_by ,process_date ,status, b_no ,mapping_error ,err_msg ,workflow_process_date,file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,source_path AS cdr_source_path ,filter_dtm ,create_by ,SYSDATE as process_date ,status, b_no ,mapping_error ,mapping_error_msg AS err_msg ,workflow_process_date,file_date FROM DSSDEV.tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM DSSDEV.tb_transaction_ss_esim_temp WHERE workflow_process_date = (SELECT  workflow_process_date FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status = 'UNMAP' AND chk_dup_append = 0 )
) WHERE 1=0
